-- PREPARED ONLY: X-01..X-08 connected Web/Desktop privacy evidence workspace.
-- Not applied. Existing privacy, client, employee, document, request and audit originals are read only.
-- Runtime gates still required: PostgreSQL/PostgREST/RLS/grants, two sessions, lock/rollback,
-- legacy/native writers, provider sandboxes, browser/layout and qualified care/privacy/legal acceptance.
begin;
create schema if not exists privacy_evidence_private;
revoke all on schema privacy_evidence_private from public,anon,authenticated;
create table if not exists privacy_evidence_private.roots(tenant_id uuid primary key,head_id uuid,updated_at timestamptz not null default clock_timestamp());
create table if not exists privacy_evidence_private.events(id uuid primary key,tenant_id uuid not null,sequence bigint not null,previous_id uuid,request_id uuid not null,actor_id uuid not null,actor_name text not null,occurred_at timestamptz not null,recorded_at timestamptz not null default clock_timestamp(),kind text not null,command jsonb not null,unique(tenant_id,sequence),unique(tenant_id,request_id));
alter table privacy_evidence_private.roots enable row level security;alter table privacy_evidence_private.events enable row level security;
revoke all on all tables in schema privacy_evidence_private from public,anon,authenticated;
create or replace function privacy_evidence_private.immutable()returns trigger language plpgsql security definer set search_path='' as $$begin raise exception using errcode='P0P01',message='Datenschutzverlauf bleibt unveränderlich.';end$$;
drop trigger if exists privacy_evidence_roots_delete on privacy_evidence_private.roots;create trigger privacy_evidence_roots_delete before delete on privacy_evidence_private.roots for each row execute function privacy_evidence_private.immutable();
drop trigger if exists privacy_evidence_events_immutable on privacy_evidence_private.events;create trigger privacy_evidence_events_immutable before update or delete on privacy_evidence_private.events for each row execute function privacy_evidence_private.immutable();

create or replace function privacy_evidence_private.profile_has(t uuid,a uuid,keys text[])returns boolean language sql stable set search_path='' as $$
select exists(select 1 from public.profiles p join public.roles r on r.id=p.role_id where p.id=a and p.tenant_id=t and p.is_active and p.status='active'and not exists(select 1 from unnest(keys)k where not case when exists(select 1 from public.role_permission_sets z where z.tenant_id=t and z.role_key=r.key)then exists(select 1 from public.role_permission_sets z where z.tenant_id=t and z.role_key=r.key and z.permission_key=k)else exists(select 1 from public.role_permissions z where z.role_id=r.id and z.permission_key=k)end))$$;
create or replace function privacy_evidence_private.kind_right(k text)returns text language sql immutable set search_path='' as $$select case
 when k in('processing_purpose_draft','legal_basis_review','consent_grant','consent_withdrawal','consent_processing_block','provider_change_request','provider_governance_review','retention_classification','retention_hold','retention_disposition_review','access_request','identity_verification','export_scope_review','export_package','secure_delivery','access_audit_review','security_incident_report','incident_assessment','deadline_review','incident_action','incident_notification','incident_closure','legal_review_revision','correction')then'security.manage'end$$;
create or replace function privacy_evidence_private.extra_rights(k text)returns text[] language sql immutable set search_path='' as $$select array[]::text[]$$;
create or replace function privacy_evidence_private.actor(t uuid,a uuid,k text default null)returns text language plpgsql security definer set search_path='' as $$
declare sid uuid;n text;permission text;required text[]:=array['security.view','office.clients.view','office.clients.view_sensitive','office.employees.view','office.employees.view_sensitive'];begin
 if auth.uid()is null or public.resolve_current_profile_id()is distinct from a or public.current_tenant_id()is distinct from t or coalesce((auth.jwt()->>'exp')::bigint,0)<=extract(epoch from clock_timestamp())then raise exception using errcode='42501',message='Aktuelles eigenes Konto fehlt.';end if;
 sid:=nullif(auth.jwt()->>'session_id','')::uuid;perform 1 from auth.sessions s where s.id=sid and s.user_id=auth.uid()and(s.not_after is null or s.not_after>clock_timestamp())for share;if not found then raise exception using errcode='42501',message='Aktuelle native Sitzung fehlt.';end if;
 permission:=privacy_evidence_private.kind_right(k);if k is not null and permission is null then raise exception using errcode='22023',message='Datenschutzvorgang ist unbekannt.';end if;if permission is not null then required:=required||permission||privacy_evidence_private.extra_rights(k);lock table public.roles,public.role_permissions,public.role_permission_sets in share mode;end if;
 select coalesce(nullif(btrim(p.display_name),''),'Name nicht bestätigt')into n from public.profiles p join public.roles r on r.id=p.role_id where p.id=a and p.tenant_id=t and p.is_active and p.status='active'and(p.auth_user_id is null or p.auth_user_id=auth.uid())for share of p,r;
 if n is null or not privacy_evidence_private.profile_has(t,a,required)then raise exception using errcode='42501',message='Aktuelle Security-, Pflegefall- oder Personalrechte fehlen.';end if;foreach permission in array required loop if public.has_permission(permission)is not true then raise exception using errcode='42501',message='Nativer Rechtezugang fehlt.';end if;end loop;return n;
end$$;

create or replace function privacy_evidence_private.sources(t uuid)returns jsonb language sql security definer set search_path='' as $$with s as(
 select'profile'::text kind,x.id,to_jsonb(x)snapshot from public.profiles x where x.tenant_id=t and x.is_active
 union all select'client',x.id,to_jsonb(x)from public.clients x where x.tenant_id=t
 union all select'client_document',x.id,to_jsonb(x)from public.client_documents x where x.tenant_id=t
 union all select'processing_activity',x.id,to_jsonb(x)from public.privacy_processing_activities x where x.tenant_id=t
 union all select'processing_purpose_source',x.id,to_jsonb(x)from public.privacy_processing_activities x where x.tenant_id=t
 union all select'legal_source',x.id,to_jsonb(x)from public.retention_rules x where x.tenant_id=t
 union all select'permission_evidence',x.id,to_jsonb(x)from public.privacy_audit_events x where x.tenant_id=t
 union all select'consent',x.id,to_jsonb(x)from public.consent_records x where x.tenant_id=t
 union all select'consent_document',x.id,to_jsonb(x)from public.consent_records x where x.tenant_id=t
 union all select'consent_event',x.id,to_jsonb(x)from public.consent_records x where x.tenant_id=t and x.revoked_at is not null
 union all select'provider',x.id,to_jsonb(x)from public.privacy_dpa_records x where x.tenant_id=t
 union all select'integration',x.id,to_jsonb(x)from public.privacy_dpa_records x where x.tenant_id=t
 union all select'dpa_agreement',x.id,to_jsonb(x)from public.privacy_dpa_records x where x.tenant_id=t
 union all select'tom_assessment',x.id,to_jsonb(x)from public.privacy_tom_records x where x.tenant_id=t
 union all select'subprocessor',x.id,to_jsonb(x)from public.privacy_dpa_records x where x.tenant_id=t
 union all select'retention_rule',x.id,to_jsonb(x)from public.retention_rules x where x.tenant_id=t
 union all select'retention_trigger',x.id,to_jsonb(x)from public.data_deletion_requests x where x.tenant_id=t
 union all select'retention_hold',x.id,to_jsonb(x)from public.data_deletion_requests x where x.tenant_id=t and x.retention_blocked
 union all select'data_subject_request',x.id,to_jsonb(x)from public.data_subject_requests x where x.tenant_id=t
 union all select'request_channel',x.id,to_jsonb(x)from public.data_subject_requests x where x.tenant_id=t
 union all select'identity_verification',x.id,to_jsonb(x)from public.data_subject_requests x where x.tenant_id=t
 union all select'subject_record',x.id,to_jsonb(x)from public.clients x where x.tenant_id=t
 union all select'export_manifest',x.id,to_jsonb(x)from public.data_export_jobs x where x.tenant_id=t
 union all select'export_delivery',x.id,to_jsonb(x)from public.data_export_jobs x where x.tenant_id=t
 union all select'access_audit',x.id,to_jsonb(x)from public.privacy_audit_events x where x.tenant_id=t
 union all select'security_incident',x.id,to_jsonb(x)from public.privacy_incident_reports x where x.tenant_id=t
 union all select'incident_assessment',x.id,to_jsonb(x)from public.privacy_incident_reports x where x.tenant_id=t
 union all select'incident_deadline_review',x.id,to_jsonb(x)from public.privacy_incident_reports x where x.tenant_id=t
 union all select'incident_action',x.id,to_jsonb(x)from public.privacy_incident_reports x where x.tenant_id=t
 union all select'incident_notification',x.id,to_jsonb(x)from public.privacy_incident_reports x where x.tenant_id=t
 union all select'incident_closure',x.id,to_jsonb(x)from public.privacy_incident_reports x where x.tenant_id=t and x.status='closed'
 union all select'legal_review_subject',x.id,to_jsonb(x)from public.privacy_audit_events x where x.tenant_id=t
 union all select'legal_requirement',x.id,to_jsonb(x)from public.retention_rules x where x.tenant_id=t
 union all select'reviewer_qualification',x.id,to_jsonb(x)from public.profiles x where x.tenant_id=t and x.is_active
)select coalesce(jsonb_agg(jsonb_build_object('kind',kind,'id',id,'snapshot',snapshot)order by kind,id),'[]'::jsonb)from s$$;

create or replace function privacy_evidence_private.source_rules(k text)returns jsonb language sql immutable set search_path='' as $$select case k
 when'processing_purpose_draft'then'{"activity":["processing_activity"],"purposeSource":["processing_purpose_source"],"responsible":["profile"]}'
 when'legal_basis_review'then'{"activity":["processing_activity"],"legalSource":["legal_source"],"permission":["permission_evidence"]}'
 when'consent_grant'then'{"consent":["consent"],"document":["consent_document"],"subject":["client","profile"]}'
 when'consent_withdrawal'then'{"consent":["consent"],"withdrawal":["consent_event"],"subject":["client","profile"]}'
 when'consent_processing_block'then'{"withdrawal":["consent_event"],"activity":["processing_activity"],"permission":["permission_evidence"]}'
 when'provider_change_request'then'{"provider":["provider"],"integration":["integration"],"agreement":["dpa_agreement"]}'
 when'provider_governance_review'then'{"provider":["provider"],"agreement":["dpa_agreement"],"tom":["tom_assessment"],"subprocessor":["subprocessor"]}'
 when'retention_classification'then'{"document":["client_document","subject_record"],"rule":["retention_rule"],"trigger":["retention_trigger"]}'
 when'retention_hold'then'{"document":["client_document","subject_record"],"hold":["retention_hold"],"responsible":["profile"]}'
 when'retention_disposition_review'then'{"document":["client_document","subject_record"],"rule":["retention_rule"],"trigger":["retention_trigger"]}'
 when'access_request'then'{"request":["data_subject_request"],"subject":["client","profile"],"channel":["request_channel"]}'
 when'identity_verification'then'{"request":["data_subject_request"],"verification":["identity_verification"]}'
 when'export_scope_review'then'{"request":["data_subject_request"],"subjectRecord":["subject_record"],"permission":["permission_evidence"]}'
 when'export_package'then'{"request":["data_subject_request"],"manifest":["export_manifest"]}'
 when'secure_delivery'then'{"request":["data_subject_request"],"manifest":["export_manifest"],"delivery":["export_delivery"]}'
 when'access_audit_review'then'{"audit":["access_audit"],"actor":["profile"],"subject":["client","profile"]}'
 when'security_incident_report'then'{"incident":["security_incident"],"reporter":["profile"],"permission":["permission_evidence"]}'
 when'incident_assessment'then'{"incident":["security_incident"],"assessment":["incident_assessment"],"reviewer":["profile"]}'
 when'deadline_review'then'{"incident":["security_incident"],"assessment":["incident_assessment"],"legalSource":["legal_source"]}'
 when'incident_action'then'{"incident":["security_incident"],"assessment":["incident_assessment"],"action":["incident_action"]}'
 when'incident_notification'then'{"incident":["security_incident"],"deadline":["incident_deadline_review"],"notification":["incident_notification"]}'
 when'incident_closure'then'{"incident":["security_incident"],"assessment":["incident_assessment"],"closure":["incident_closure"]}'
 when'legal_review_revision'then'{"subject":["legal_review_subject"],"requirement":["legal_requirement"],"qualification":["reviewer_qualification"],"reviewer":["profile"]}'
 when'correction'then'{}'end::jsonb$$;
create or replace function privacy_evidence_private.field_keys(k text)returns text[] language sql immutable set search_path='' as $$select case k
 when'processing_purpose_draft'then array['purpose','categoryScopeSha256','status']when'legal_basis_review'then array['layer','decision','sourceSha256','reason']
 when'consent_grant'then array['scopeSha256','grantedAt','validity']when'consent_withdrawal'then array['withdrawnAt','scopeSha256','reason']when'consent_processing_block'then array['decision','effectiveAt','reason']
 when'provider_change_request'then array['changeSha256','requestedFor','state']when'provider_governance_review'then array['decision','scopeSha256','reason']
 when'retention_classification'then array['classCode','candidateUntil','reason']when'retention_hold'then array['decision','effectiveAt','reason']when'retention_disposition_review'then array['decision','reviewedAt','evidenceSha256','reason']
 when'access_request'then array['requestType','receivedAt','dueAt']when'identity_verification'then array['decision','verifiedAt','evidenceSha256']when'export_scope_review'then array['scopeSha256','decision','reason']when'export_package'then array['packageSha256','generatedAt','state']when'secure_delivery'then array['state','observedAt','receiptSha256']
 when'access_audit_review'then array['purposeCode','decision','reviewedAt','reviewEvidenceSha256']when'security_incident_report'then array['categoryCode','detectedAt','evidenceSha256']when'incident_assessment'then array['riskLevel','rightsRisk','rationaleSha256']when'deadline_review'then array['deadlineType','deadlineAt','ruleVersion','decision']when'incident_action'then array['state','dueAt','resultSha256']when'incident_notification'then array['notificationType','submittedAt','acknowledgementSha256']when'incident_closure'then array['outcome','closedAt','closureSha256','openConsequence']
 when'legal_review_revision'then array['decision','reviewedAt','scopeSha256','limitations']when'correction'then array['targetId','reason','evidenceSha256']end$$;

create or replace function privacy_evidence_private.validate_command(cmd jsonb,src jsonb)returns void language plpgsql set search_path='' as $$declare k text:=cmd->>'kind';p jsonb:=cmd->'payload';rules jsonb:=privacy_evidence_private.source_rules(k);actual text[];expected text[];entry record;v jsonb;begin
 select array_agg(x order by x)into actual from jsonb_object_keys(cmd)x;if jsonb_typeof(cmd)is distinct from'object'or actual is distinct from array['actorId','eventId','expectedHeadId','kind','note','occurredAt','payload','requestId','tenantId','version']::text[]or cmd->>'version'<>'2026-10-16.1'or privacy_evidence_private.kind_right(k)is null or cmd->>'requestId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'or cmd->>'eventId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'or cmd->>'tenantId'!~'^[0-9a-f-]{36}$'or cmd->>'actorId'!~'^[0-9a-f-]{36}$'or(cmd->'expectedHeadId'<>'null'::jsonb and cmd->>'expectedHeadId'!~'^[0-9a-f-]{36}$')or cmd->>'occurredAt'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'or nullif(btrim(cmd->>'note'),'')is null or length(cmd->>'note')>4000 or jsonb_typeof(p)is distinct from'object'or rules is null then raise exception using errcode='22023',message='Datenschutzanfrage ist unvollständig.';end if;
 select array_agg(key order by key)into expected from(select jsonb_object_keys(rules)key union all select unnest(privacy_evidence_private.field_keys(k)))q;select array_agg(x order by x)into actual from jsonb_object_keys(p)x;if actual is distinct from expected then raise exception using errcode='22023',message='Vorgangsfelder sind unvollständig oder enthalten Fremdfelder.';end if;
 for entry in select key,value from jsonb_each(rules)loop v:=p->entry.key;if jsonb_typeof(v)is distinct from'object'or(select array_agg(x order by x)from jsonb_object_keys(v)x)is distinct from array['id','kind','snapshot']::text[]or not exists(select 1 from jsonb_array_elements(entry.value)x where x#>>'{}'=v->>'kind')or v->>'id'!~'^[0-9a-f-]{36}$'or jsonb_typeof(v->'snapshot')is distinct from'object'or v#>>'{snapshot,id}'is distinct from v->>'id'or not exists(select 1 from jsonb_array_elements(src)x where x=v)then raise exception using errcode='40001',message='Originalquelle ist falsch, geändert oder nicht mehr zugänglich.';end if;end loop;
 for entry in select x key from unnest(privacy_evidence_private.field_keys(k))x loop if nullif(btrim(p->>entry.key),'')is null then raise exception using errcode='22023',message='Pflichtangabe fehlt.';end if;if entry.key~'(Sha256)$'and(p->>entry.key)!~'^[0-9a-f]{64}$'then raise exception using errcode='22023',message='Fingerabdruck ist ungültig.';elsif entry.key in('grantedAt','withdrawnAt','effectiveAt','requestedFor','candidateUntil','reviewedAt','receivedAt','dueAt','verifiedAt','generatedAt','observedAt','detectedAt','deadlineAt','submittedAt','closedAt')and(p->>entry.key)!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'then raise exception using errcode='22007',message='Zeitpunkt ist ungültig.';elsif entry.key='targetId'and(p->>entry.key)!~'^[0-9a-f-]{36}$'then raise exception using errcode='22P02',message='UUID ist ungültig.';end if;end loop;
end$$;

create or replace function privacy_evidence_private.event_json(e privacy_evidence_private.events)returns jsonb language sql immutable set search_path='' as $$select jsonb_build_object('id',e.id,'sequence',e.sequence,'previousId',e.previous_id,'tenantId',e.tenant_id,'actorId',e.actor_id,'actorName',e.actor_name,'recordedAt',to_char(e.recorded_at at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'command',e.command)$$;
create or replace function privacy_evidence_private.history(t uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare e privacy_evidence_private.events%rowtype;head uuid;prev uuid;n bigint:=0;rows jsonb:='[]';begin select r.head_id into head from privacy_evidence_private.roots r where r.tenant_id=t;for e in select*from privacy_evidence_private.events z where z.tenant_id=t order by z.sequence loop if e.sequence<>n+1 or e.previous_id is distinct from prev or e.command->>'eventId'is distinct from e.id::text or e.command->>'tenantId'is distinct from t::text or e.command->>'actorId'is distinct from e.actor_id::text or(e.command->>'expectedHeadId')is distinct from prev::text then raise exception using errcode='23514',message='Datenschutzverlauf ist widersprüchlich.';end if;rows:=rows||jsonb_build_array(privacy_evidence_private.event_json(e));prev:=e.id;n:=n+1;end loop;if head is distinct from prev then raise exception using errcode='23514',message='Datenschutzverlaufskopf ist unvollständig.';end if;return jsonb_build_object('version','2026-10-16.1','tenantId',t,'count',n,'headId',head,'events',rows);end$$;
create or replace function privacy_evidence_private.read_context(t uuid,a uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare n text;src jsonb;begin n:=privacy_evidence_private.actor(t,a,null);src:=privacy_evidence_private.sources(t);return jsonb_build_object('version','2026-10-16.1','tenantId',t,'actorId',a,'loadedAt',to_char(clock_timestamp()at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'sources',jsonb_build_object('count',jsonb_array_length(src),'rows',src),'history',privacy_evidence_private.history(t));end$$;
create or replace function privacy_evidence_private.commit_event(cmd jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare t uuid:=(cmd->>'tenantId')::uuid;a uuid:=(cmd->>'actorId')::uuid;rid uuid:=(cmd->>'requestId')::uuid;eid uuid:=(cmd->>'eventId')::uuid;n text;root privacy_evidence_private.roots%rowtype;e privacy_evidence_private.events%rowtype;src jsonb;begin n:=privacy_evidence_private.actor(t,a,cmd->>'kind');perform pg_advisory_xact_lock(hashtextextended('privacy-evidence:'||t::text,0));insert into privacy_evidence_private.roots(tenant_id)values(t)on conflict do nothing;select*into root from privacy_evidence_private.roots r where r.tenant_id=t for update;select*into e from privacy_evidence_private.events z where z.tenant_id=t and z.request_id=rid;if e.id is not null then if e.command is distinct from cmd then raise exception using errcode='23505',message='Anfragekennung gehört zu anderem Inhalt.';end if;return jsonb_build_object('version','2026-10-16.1','requestId',rid,'command',e.command,'event',privacy_evidence_private.event_json(e));end if;src:=privacy_evidence_private.sources(t);perform privacy_evidence_private.validate_command(cmd,src);if(cmd->>'expectedHeadId')is distinct from root.head_id::text then raise exception using errcode='40001',message='Datenschutzverlauf wurde geändert.';end if;if cmd->>'kind'='correction'and not exists(select 1 from privacy_evidence_private.events x where x.tenant_id=t and x.id=(cmd#>>'{payload,targetId}')::uuid and x.kind<>'correction'and not exists(select 1 from privacy_evidence_private.events z where z.tenant_id=t and z.kind='correction'and z.command#>>'{payload,targetId}'=x.id::text))then raise exception using errcode='23514',message='Nur ein vorhandenes unberichtigtes Original kann berichtigt werden.';end if;insert into privacy_evidence_private.events(id,tenant_id,sequence,previous_id,request_id,actor_id,actor_name,occurred_at,kind,command)values(eid,t,coalesce((select max(sequence)+1 from privacy_evidence_private.events where tenant_id=t),1),root.head_id,rid,a,n,(cmd->>'occurredAt')::timestamptz,cmd->>'kind',cmd)returning*into e;update privacy_evidence_private.roots set head_id=eid,updated_at=clock_timestamp()where tenant_id=t;return jsonb_build_object('version','2026-10-16.1','requestId',rid,'command',cmd,'event',privacy_evidence_private.event_json(e));end$$;
create or replace function privacy_evidence_private.confirm_event(t uuid,a uuid,rid uuid,cmd jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare e privacy_evidence_private.events%rowtype;begin perform privacy_evidence_private.actor(t,a,null);select*into e from privacy_evidence_private.events z where z.tenant_id=t and z.request_id=rid;if e.id is null or e.command is distinct from cmd or e.actor_id<>a then raise exception using errcode='P0P01',message='Passende native Quittung fehlt.';end if;return jsonb_build_object('version','2026-10-16.1','requestId',rid,'command',e.command,'event',privacy_evidence_private.event_json(e));end$$;
create or replace function public.web_privacy_evidence_workspace_context(p_tenant_id uuid,p_actor_id uuid)returns jsonb language sql security invoker set search_path='' as $$select privacy_evidence_private.read_context(p_tenant_id,p_actor_id)$$;
create or replace function public.web_commit_privacy_evidence_event(p_command jsonb)returns jsonb language sql security invoker set search_path='' as $$select privacy_evidence_private.commit_event(p_command)$$;
create or replace function public.web_confirm_privacy_evidence_event(p_tenant_id uuid,p_actor_id uuid,p_request_id uuid,p_command jsonb)returns jsonb language sql security invoker set search_path='' as $$select privacy_evidence_private.confirm_event(p_tenant_id,p_actor_id,p_request_id,p_command)$$;
revoke all on function public.web_privacy_evidence_workspace_context(uuid,uuid),public.web_commit_privacy_evidence_event(jsonb),public.web_confirm_privacy_evidence_event(uuid,uuid,uuid,jsonb)from public,anon;
grant usage on schema privacy_evidence_private to authenticated;
grant execute on function privacy_evidence_private.read_context(uuid,uuid),privacy_evidence_private.commit_event(jsonb),privacy_evidence_private.confirm_event(uuid,uuid,uuid,jsonb)to authenticated;
grant execute on function public.web_privacy_evidence_workspace_context(uuid,uuid),public.web_commit_privacy_evidence_event(jsonb),public.web_confirm_privacy_evidence_event(uuid,uuid,uuid,jsonb)to authenticated;
commit;
